// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
import "forge-std/Test.sol";
import "contracts/lib/ERC8211.sol";
contract CallDecodeBase {
    function decode(bytes calldata p) external pure returns (address,bytes memory) { return abi.decode(p,(address,bytes)); }
}
contract CallDecodeGuard {
    function decode(bytes calldata p) external pure returns (address,bytes memory) {
        assembly ("memory-safe") {
            if lt(p.length,64) { revert(0,0) }
            let off := calldataload(add(p.offset,32))
            if gt(off,sub(p.length,32)) { revert(0,0) }
            let n := calldataload(add(p.offset,off))
            if gt(n,sub(sub(p.length,off),32)) { revert(0,0) }
        }
        return abi.decode(p,(address,bytes));
    }
}
contract OrDecodeBase {
    function decode(bytes memory p) external pure returns (Constraint[] memory) { return abi.decode(p,(Constraint[])); }
}
contract OrDecodeGuard {
    function decode(bytes memory p) external pure returns (Constraint[] memory) {
        assembly ("memory-safe") {
            let size := mload(p)
            if lt(size,32) { revert(0,0) }
            let start := add(p,32)
            let off := mload(start)
            if gt(off,sub(size,32)) { revert(0,0) }
            let count := mload(add(start,off))
            let table := add(off,32)
            if gt(count,div(sub(size,table),32)) { revert(0,0) }
            for { let i := 0 } lt(i,count) { i := add(i,1) } {
                let rel := mload(add(add(start,table),mul(i,32)))
                if lt(sub(size,table),64) { revert(0,0) }
                if gt(rel,sub(sub(size,table),64)) { revert(0,0) }
                let entry := add(table,rel)
                let dataoff := mload(add(add(start,entry),32))
                if gt(dataoff,sub(sub(size,entry),32)) { revert(0,0) }
                let head := add(entry,dataoff)
                let n := mload(add(start,head))
                if gt(n,sub(sub(size,head),32)) { revert(0,0) }
            }
        }
        return abi.decode(p,(Constraint[]));
    }
}
contract DecoderCostTest is Test {
    function test_callDecodeGuardCost() public {
        CallDecodeBase b = new CallDecodeBase(); CallDecodeGuard g = new CallDecodeGuard();
        emit log_named_uint("STATIC_CALL added runtime bytes", address(g).code.length-address(b).code.length);
        uint256[5] memory sizes=[uint256(0),4,32,256,1024];
        for(uint256 i;i<sizes.length;i++) {
            bytes memory p=abi.encode(address(0x1234),new bytes(sizes[i]));
            uint256 a=gasleft(); b.decode(p); a-=gasleft();
            uint256 z=gasleft(); g.decode(p); z-=gasleft();
            emit log_named_uint("call data bytes",sizes[i]); emit log_named_uint("extra gas",z-a);
        }
    }
    function test_orDecodeGuardCost() public {
        OrDecodeBase b = new OrDecodeBase(); OrDecodeGuard g = new OrDecodeGuard();
        emit log_named_uint("OR added runtime bytes", address(g).code.length-address(b).code.length);
        uint256[5] memory sizes=[uint256(0),1,2,4,8];
        for(uint256 i;i<sizes.length;i++) {
            Constraint[] memory c=new Constraint[](sizes[i]); for(uint256 j;j<c.length;j++) c[j]=Constraint(ConstraintType.EQ,abi.encode(uint256(1)));
            bytes memory p=abi.encode(c);
            uint256 a=gasleft(); b.decode(p); a-=gasleft();
            uint256 z=gasleft(); g.decode(p); z-=gasleft();
            emit log_named_uint("OR entries",sizes[i]); emit log_named_uint("extra gas",z-a);
        }
    }
}
